SELECT ROUND(
  COALESCE(
    (SELECT COUNT(*) FROM (SELECT DISTINCT sender_id, receiver_id FROM accepted) AS a) * 1.0
    / NULLIF((SELECT COUNT(*) FROM (SELECT DISTINCT sender_id, receiver_id FROM requests) AS r), 0),
    0
  ), 2) AS accept_rate;

